import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 계좌번호 암호화 키는 키 관리 방식이 정해지기 전까지 상수로 둔다.
const ACCOUNT_ENC_KEY = 'partner-account-enc-key';
const ROLE = '예산·회계 담당자';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(422, 'PARTNER_INPUT_INVALID', message);
}

function text(value: unknown, max: number, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

function dateOf(value: unknown, label: string): string | null {
  const v = text(value, 10, label);
  if (v !== null && !DATE_RE.test(v)) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return v;
}

function parsePartner(data: Record<string, unknown>) {
  const partnerType = text(data['partnerType'], 10, '거래처 유형');
  const partnerName = text(data['partnerName'], 200, '거래처 명칭');
  const partnerCode = text(data['partnerCode'], 30, '거래처 코드');
  if (partnerType === null || partnerName === null || partnerCode === null) {
    throw invalid('필수 값을 입력해 주세요.');
  }
  if (partnerType !== '일반' && partnerType !== '금융') {
    throw invalid('거래처 유형은 일반 또는 금융이어야 합니다.');
  }
  if (typeof data['taxInvoiceYn'] !== 'boolean') {
    throw invalid('세금계산서 여부를 선택해 주세요.');
  }
  let projectId: string | null = null;
  const rawProject = data['projectId'];
  if (rawProject !== undefined && rawProject !== null && rawProject !== '') {
    if (!/^\d+$/.test(String(rawProject))) {
      throw invalid('프로젝트 형식이 올바르지 않습니다.');
    }
    projectId = String(rawProject);
  }
  const tradeStartDate = dateOf(data['tradeStartDate'], '거래 시작일');
  const tradeEndDate = dateOf(data['tradeEndDate'], '거래 종료일');
  if (tradeStartDate !== null && tradeEndDate !== null && tradeEndDate < tradeStartDate) {
    throw invalid('거래 종료일은 시작일보다 빠를 수 없습니다.');
  }
  const businessRegNo = text(data['businessRegNo'], 10, '사업자등록번호');
  if (businessRegNo !== null && !/^\d+$/.test(businessRegNo)) {
    throw invalid('사업자등록번호는 숫자만 입력해 주세요.');
  }
  return {
    partnerType,
    partnerName,
    partnerCode,
    taxInvoiceYn: data['taxInvoiceYn'] as boolean,
    projectId,
    tradeStartDate,
    tradeEndDate,
    businessRegNo,
    partnerShortName: text(data['partnerShortName'], 100, '거래처 약칭'),
    representativeName: text(data['representativeName'], 100, '대표자명'),
    partnerCategory: text(data['partnerCategory'], 100, '거래처 분류'),
    region: text(data['region'], 100, '지역'),
    contactName: text(data['contactName'], 100, '담당자명'),
    contactPhone: text(data['contactPhone'], 30, '담당자 연락처'),
  };
}

@Controller('api/v1')
export class FnSfr00204Controller {
  @Post('/partners')
  @HttpCode(200)
  async createPartner(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const p = parsePartner(data);
    const bankName = text(data['bankName'], 100, '은행명');
    const accountHolder = text(data['accountHolder'], 100, '예금주');
    const rawAccountNo = data['accountNo'];
    if (rawAccountNo !== undefined && rawAccountNo !== null && typeof rawAccountNo !== 'string') {
      throw invalid('계좌번호 형식이 올바르지 않습니다.');
    }
    const accountNo = rawAccountNo ? (rawAccountNo as string) : null;
    const hasAccount = bankName !== null || accountNo !== null || accountHolder !== null;
    if (hasAccount && p.partnerType !== '금융') {
      throw new ApiError(422, 'PARTNER_ACCOUNT_NOT_ALLOWED', '일반 거래처에는 계좌정보를 등록할 수 없습니다.');
    }
    if (hasAccount && (bankName === null || accountNo === null)) {
      throw invalid('계좌정보는 은행명과 계좌번호를 함께 입력해 주세요.');
    }
    return transaction(async (db) => {
      if (p.projectId !== null) {
        const projects = await db.query(
          'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
          { projectId: p.projectId },
        );
        if (projects.length === 0) {
          throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
        }
      }
      const dup = await db.query(
        'SELECT partner_id FROM partner WHERE partner_code = :partnerCode',
        { partnerCode: p.partnerCode },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'PARTNER_CODE_DUPLICATED', '이미 사용 중인 거래처 코드입니다.');
      }
      const rows = await db.query(
        'INSERT INTO partner (project_id, partner_code, partner_name, partner_short_name, partner_type, business_reg_no, representative_name, partner_category, region, tax_invoice_yn, trade_start_date, trade_end_date, contact_name, contact_phone, created_at, updated_at) ' +
          'VALUES (CAST(:projectId AS bigint), :partnerCode, :partnerName, :partnerShortName, :partnerType, :businessRegNo, :representativeName, :partnerCategory, :region, :taxInvoiceYn, CAST(:tradeStartDate AS date), CAST(:tradeEndDate AS date), :contactName, :contactPhone, now(), now()) ' +
          'RETURNING partner_id AS "partnerId"',
        p,
      );
      const partnerId = rows[0]['partnerId'];
      if (hasAccount) {
        // 가정: use_yn 고정값 '사용'. 계좌번호는 암호화해 저장한다.
        await db.execute(
          'INSERT INTO partner_account (partner_id, bank_name, account_no_enc, account_holder, use_yn, created_at, updated_at) ' +
            "VALUES (CAST(:partnerId AS bigint), :bankName, encode(pgp_sym_encrypt(CAST(:accountNo AS text), :encKey), 'base64'), :accountHolder, '사용', now(), now())",
          { partnerId, bankName, accountNo, accountHolder, encKey: ACCOUNT_ENC_KEY },
        );
      }
      return { partnerId };
    });
  }

  @Put('/partners/:partnerId')
  async updatePartner(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const partnerId = req.params['partnerId'];
    const data = checks.inputOf(req.body);
    if (!/^\d+$/.test(partnerId)) {
      throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처를 찾을 수 없습니다.');
    }
    const p = parsePartner(data);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT partner_id FROM partner WHERE partner_id = CAST(:partnerId AS bigint)',
        { partnerId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PARTNER_NOT_FOUND', '거래처를 찾을 수 없습니다.');
      }
      if (p.projectId !== null) {
        const projects = await db.query(
          'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
          { projectId: p.projectId },
        );
        if (projects.length === 0) {
          throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
        }
      }
      const dup = await db.query(
        'SELECT partner_id FROM partner WHERE partner_code = :partnerCode AND partner_id <> CAST(:partnerId AS bigint)',
        { partnerCode: p.partnerCode, partnerId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'PARTNER_CODE_DUPLICATED', '이미 사용 중인 거래처 코드입니다.');
      }
      await db.execute(
        'UPDATE partner SET project_id = CAST(:projectId AS bigint), partner_code = :partnerCode, partner_name = :partnerName, partner_short_name = :partnerShortName, partner_type = :partnerType, business_reg_no = :businessRegNo, representative_name = :representativeName, partner_category = :partnerCategory, region = :region, tax_invoice_yn = :taxInvoiceYn, trade_start_date = CAST(:tradeStartDate AS date), trade_end_date = CAST(:tradeEndDate AS date), contact_name = :contactName, contact_phone = :contactPhone, updated_at = now() ' +
          'WHERE partner_id = CAST(:partnerId AS bigint)',
        { ...p, partnerId },
      );
      return { partnerId: Number(partnerId) };
    });
  }

  @Get('/partners')
  async listPartners(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageNo = Math.max(0, Number(query['page'] ?? 0) || 0);
    const size = Math.min(200, Math.max(1, Number(query['size'] ?? 20) || 20));
    const partnerName = query['partnerName'] ? String(query['partnerName']) : null;
    const partnerType = query['partnerType'] ? String(query['partnerType']) : null;
    return transaction(async (db) => {
      const where =
        "WHERE (CAST(:partnerName AS text) IS NULL OR partner_name ILIKE '%' || CAST(:partnerName AS text) || '%') " +
        'AND (CAST(:partnerType AS text) IS NULL OR partner_type = CAST(:partnerType AS text))';
      const totals = await db.query('SELECT COUNT(*) AS total FROM partner ' + where, { partnerName, partnerType });
      const items = await db.query(
        'SELECT partner_id AS "partnerId", partner_code AS "partnerCode", partner_name AS "partnerName", partner_type AS "partnerType", business_reg_no AS "businessRegNo", representative_name AS "representativeName" ' +
          'FROM partner ' + where + ' ORDER BY partner_id DESC LIMIT :size OFFSET :offset',
        { partnerName, partnerType, size, offset: pageNo * size },
      );
      return { items, page: pageNo, size, total: Number(totals[0]['total']) };
    });
  }
}

