import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Form, Field,
  TextInput, DateInput, Select, LookupSelect, Tiles, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const TYPES: [string, string][] = [['일반', '일반'], ['금융', '금융']];
const YN: [string, string][] = [['true', '예'], ['false', '아니오']];

function clean(form: Row): Row {
  const body: Row = {};
  Object.keys(form).forEach((k) => {
    const v = form[k];
    if (v !== '' && v !== undefined && v !== null) {
      body[k] = v;
    }
  });
  return body;
}

function PartnerForm({ role, initial, partnerId, onDone }: {
  role: string;
  initial: Row;
  partnerId?: unknown;
  onDone: (message: string) => void;
}) {
  const [form, setForm] = useState<Row>(initial);
  const editing = partnerId !== undefined;
  const set = (key: string, v: unknown) => setForm({ ...form, [key]: v });
  const text = (key: string, label: string, required?: boolean) => (
    <Field label={label} required={required}>
      <TextInput value={form[key]} onChange={(v) => set(key, v)} />
    </Field>
  );
  const submit = async () => {
    if (!form['partnerType'] || !form['partnerName'] || !form['partnerCode'] || form['taxInvoiceYn'] === undefined || form['taxInvoiceYn'] === '') {
      throw new Error('필수 값을 입력해 주세요.');
    }
    const body = clean(form);
    if (editing) {
      await call('PUT', '/partners/' + String(partnerId), role, body);
      onDone('거래처를 수정했습니다.');
    } else {
      await call('POST', '/partners', role, body);
      onDone('거래처를 등록했습니다.');
    }
  };
  return (
    <Form onSubmit={submit} submit={editing ? '수정' : '등록'}>
      <Field label='거래처 유형' required>
        <Select value={form['partnerType']} onChange={(v) => set('partnerType', v)} options={TYPES} />
      </Field>
      {text('partnerName', '거래처 명칭', true)}
      {text('partnerShortName', '거래처 약칭')}
      {text('partnerCode', '거래처 코드', true)}
      {text('businessRegNo', '사업자등록번호')}
      {text('representativeName', '대표자명')}
      <Field label='프로젝트'>
        <LookupSelect table='project' role={role} value={form['projectId']} onChange={(v) => set('projectId', v)} />
      </Field>
      {text('partnerCategory', '거래처 분류')}
      {text('region', '지역')}
      <Field label='세금계산서 여부' required>
        <Select
          value={form['taxInvoiceYn'] === undefined ? '' : String(form['taxInvoiceYn'])}
          onChange={(v) => set('taxInvoiceYn', v === '' ? '' : v === 'true')}
          options={YN}
        />
      </Field>
      <Field label='거래 시작일'>
        <DateInput value={form['tradeStartDate']} onChange={(v) => set('tradeStartDate', v)} />
      </Field>
      <Field label='거래 종료일'>
        <DateInput value={form['tradeEndDate']} onChange={(v) => set('tradeEndDate', v)} />
      </Field>
      {text('contactName', '담당자명')}
      {text('contactPhone', '담당자 연락처')}
      {!editing && form['partnerType'] === '금융' && (
        <>
          {text('bankName', '은행명')}
          {text('accountNo', '계좌번호')}
          {text('accountHolder', '예금주')}
        </>
      )}
    </Form>
  );
}

export default function FnSfr00204Page({ role, notify }: PageProps) {
  const [name, setName] = useState('');
  const [type, setType] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [drawer, setDrawer] = useState<{ mode: 'create' | 'edit'; row?: Row } | null>(null);
  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/partners', role, undefined, { ...applied, page: pageNo, size: 20 }),
    [role, applied, pageNo],
  );
  const done = (message: string) => {
    setDrawer(null);
    notify(message);
    reload();
  };
  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>거래처 현황</h2>
        <Tiles items={[['전체 거래처', data ? data.total : 0]]} />
      </section>
      <section className='box span-12'>
        <h2>거래처 목록</h2>
        <Filters
          onSearch={() => { setPageNo(0); setApplied({ partnerName: name, partnerType: type }); }}
          onReset={() => { setName(''); setType(''); setPageNo(0); setApplied({}); }}
        >
          <Field label='거래처 명칭'>
            <TextInput value={name} onChange={setName} />
          </Field>
          <Field label='거래처 유형'>
            <Select value={type} onChange={setType} options={TYPES} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={() => setDrawer({ mode: 'create' })}>거래처 등록</button>
        </Band>
        {error && <ErrorText text={error} />}
        <DataTable
          rows={data?.items ?? []}
          empty='거래처가 없습니다.'
          columns={[
            { key: 'partnerCode', label: '거래처 코드' },
            { key: 'partnerName', label: '거래처 명칭' },
            { key: 'partnerType', label: '거래처 유형', render: (r) => <Badge value={r['partnerType']} /> },
            { key: 'businessRegNo', label: '사업자등록번호' },
            { key: 'representativeName', label: '대표자명' },
            {
              key: 'partnerId',
              label: '관리',
              render: (r) => <button onClick={() => setDrawer({ mode: 'edit', row: r })}>수정</button>,
            },
          ]}
        />
        <Pager page={pageNo} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {drawer && drawer.mode === 'create' && (
        <Drawer title='거래처 등록' onClose={() => setDrawer(null)}>
          <PartnerForm role={role} initial={{}} onDone={done} />
        </Drawer>
      )}
      {drawer && drawer.mode === 'edit' && drawer.row && (
        <Drawer title='거래처 수정' onClose={() => setDrawer(null)}>
          <PartnerForm
            role={role}
            partnerId={drawer.row['partnerId']}
            initial={{
              partnerType: drawer.row['partnerType'],
              partnerName: drawer.row['partnerName'],
              partnerCode: drawer.row['partnerCode'],
              businessRegNo: drawer.row['businessRegNo'],
              representativeName: drawer.row['representativeName'],
            }}
            onDone={done}
          />
        </Drawer>
      )}
    </div>
  );
}
